#include "ui/language.h"

#include <windows.h>

#include <cwctype>

namespace dirsize::ui {

namespace {

// Generated by cmake/gen_lang.cmake: kLanguageTable.
#include "languages.inc"

bool SameIgnoringCase(std::wstring_view a, std::wstring_view b) {
    if (a.size() != b.size()) return false;
    for (size_t i = 0; i < a.size(); ++i) {
        if (std::towlower(a[i]) != std::towlower(b[i])) return false;
    }
    return true;
}

bool Serves(const LanguageEntry& e, std::wstring_view tag) {
    if (TagMatches(tag, e.locale)) return true;
    for (const wchar_t* const* m = e.matches; m && *m; ++m) {
        if (TagMatches(tag, *m)) return true;
    }
    return false;
}

}  // namespace

std::span<const LanguageEntry> Languages() { return kLanguageTable; }

bool TagMatches(std::wstring_view tag, std::wstring_view pattern) {
    if (pattern.empty() || tag.size() < pattern.size()) return false;
    if (!SameIgnoringCase(tag.substr(0, pattern.size()), pattern)) return false;
    return tag.size() == pattern.size() || tag[pattern.size()] == L'-';
}

size_t PickLanguage(const std::vector<std::wstring>& preferred, std::span<const LanguageEntry> table) {
    for (const auto& tag : preferred) {
        for (size_t i = 0; i < table.size(); ++i) {
            if (Serves(table[i], tag)) return i;
        }
    }
    return FindLanguage(L"en-US", table);
}

size_t FindLanguage(std::wstring_view name, std::span<const LanguageEntry> table) {
    for (size_t i = 0; i < table.size(); ++i) {
        if (SameIgnoringCase(name, table[i].locale)) return i;
    }
    return table.size();
}

}  // namespace dirsize::ui
